constexpr std::uint64_t asset_key(std::uint32_t registry,std::uint16_t type,std::uint16_t slot) noexcept {
    return (std::uint64_t{registry}<<32)|(std::uint64_t{type}<<16)|slot;
}
// Preserve authored catalogue order and wire slots. Only this lookup index is
// sorted; runtime resolution is bounded binary search instead of a full scan.
inline constexpr auto kAssetOrder=[] {
    std::array<std::uint16_t,std::size(kAssets)> order{};
    for(std::size_t i=0;i<order.size();++i) {order[i]=static_cast<std::uint16_t>(i);}
    std::sort(order.begin(),order.end(),[](auto a,auto b) {
        const auto& x=kAssets[a].asset;const auto& y=kAssets[b].asset;
        return asset_key(x.registry,x.type,x.slot)<asset_key(y.registry,y.type,y.slot);
    });
    return order;
}();
constexpr std::size_t catalog_index(std::uint32_t registry,std::uint16_t type,std::uint16_t slot) noexcept {
    const auto key=asset_key(registry,type,slot);std::size_t low{},high=kAssetOrder.size();
    while(low<high) {
        const auto middle=low+(high-low)/2;const auto& a=kAssets[kAssetOrder[middle]].asset;
        if(asset_key(a.registry,a.type,a.slot)<key) {low=middle+1;}else {high=middle;}
    }
    if(low==kAssetOrder.size()) {return std::size(kAssets);}
    const auto i=kAssetOrder[low];const auto& a=kAssets[i].asset;
    return asset_key(a.registry,a.type,a.slot)==key?i:std::size(kAssets);
}
constexpr const AssetBinding* find(std::uint32_t registry,std::uint16_t type,std::uint16_t slot) noexcept {
    const auto i=catalog_index(registry,type,slot);return i<std::size(kAssets)?&kAssets[i]:nullptr;
}
constexpr coo::Asset asset(std::uint32_t registry,std::uint16_t type,std::uint16_t slot) noexcept {const auto* a=find(registry,type,slot);return a?a->asset:coo::Asset{};}
